def mark_existing_investors(apps, schema_editor):
    """Pemohon yang sudah pernah mengajukan minat investasi menjadi akun investor;
    asal modal dan sektor diambil dari permintaannya."""
    Applicant = apps.get_model("alokasi", "Applicant")
    InvestmentRequest = apps.get_model("alokasi", "InvestmentRequest")
    for applicant in Applicant.objects.filter(
        investment_requests__isnull=False
    ).distinct():
        requests = InvestmentRequest.objects.filter(applicant=applicant).order_by(
            "-submitted_at", "-pk"
        )
        latest = requests.first()
        applicant.is_investor = True
        applicant.capital_origin = latest.capital_origin
        applicant.origin_country = latest.origin_country
        applicant.save(
            update_fields=["is_investor", "capital_origin", "origin_country"]
        )
        sectors = {r.sector_id for r in requests if r.sector_id}
        applicant.interest_sectors.add(*sectors)


